-- --------------------------------------------------------
-- Table structure for advance_settlements
-- --------------------------------------------------------
DROP TABLE IF EXISTS advance_settlements;
CREATE TABLE advance_settlements (
      id TEXT PRIMARY KEY,
      advance_id TEXT NOT NULL,
      date TEXT NOT NULL,
      amount INTEGER NOT NULL,
      settlement_type TEXT NOT NULL, -- cash, dues_offset
      due_year_month TEXT,
      note TEXT,
      created_at TEXT NOT NULL,
      FOREIGN KEY (advance_id) REFERENCES advances(id) ON DELETE CASCADE
    );

-- --------------------------------------------------------
-- Table structure for advances
-- --------------------------------------------------------
DROP TABLE IF EXISTS advances;
CREATE TABLE advances (
      id TEXT PRIMARY KEY,
      advance_number TEXT UNIQUE NOT NULL,
      date TEXT NOT NULL,
      resident_name TEXT NOT NULL,
      house_code TEXT,
      description TEXT NOT NULL,
      total_amount INTEGER NOT NULL,
      settled_amount INTEGER NOT NULL DEFAULT 0,
      balance INTEGER NOT NULL,
      status TEXT NOT NULL DEFAULT 'active', -- active, settled
      note TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

-- --------------------------------------------------------
-- Table structure for audit_log
-- --------------------------------------------------------
DROP TABLE IF EXISTS audit_log;
CREATE TABLE audit_log (
      id TEXT PRIMARY KEY,
      timestamp TEXT NOT NULL,
      user_name TEXT NOT NULL,
      action TEXT NOT NULL, -- CREATE, UPDATE, DELETE, LOCK, UNLOCK, IMPORT
      entity_type TEXT NOT NULL,
      entity_id TEXT NOT NULL,
      before_value TEXT,
      after_value TEXT,
      ip_address TEXT
    );

-- --------------------------------------------------------
-- Table structure for dues
-- --------------------------------------------------------
DROP TABLE IF EXISTS dues;
CREATE TABLE dues (
      id TEXT PRIMARY KEY,
      house_id TEXT NOT NULL,
      house_code TEXT NOT NULL,
      year_month TEXT NOT NULL, -- YYYY-MM
      component_id TEXT NOT NULL,
      component_name TEXT NOT NULL,
      amount INTEGER NOT NULL,
      paid_amount INTEGER NOT NULL DEFAULT 0,
      status TEXT NOT NULL DEFAULT 'belum bayar', -- belum bayar, sebagian, lunas
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      FOREIGN KEY (house_id) REFERENCES houses(id) ON DELETE CASCADE
    );

-- --------------------------------------------------------
-- Table structure for expense_categories
-- --------------------------------------------------------
DROP TABLE IF EXISTS expense_categories;
CREATE TABLE expense_categories (
      id TEXT PRIMARY KEY,
      name TEXT UNIQUE NOT NULL,
      is_default INTEGER NOT NULL DEFAULT 1
    );

-- --------------------------------------------------------
-- Table structure for expenses
-- --------------------------------------------------------
DROP TABLE IF EXISTS expenses;
CREATE TABLE expenses (
      id TEXT PRIMARY KEY,
      expense_number TEXT UNIQUE NOT NULL,
      date TEXT NOT NULL,
      category TEXT NOT NULL,
      description TEXT NOT NULL,
      amount INTEGER NOT NULL,
      payee TEXT,
      receipt_photo TEXT,
      note TEXT,
      created_by TEXT DEFAULT 'Bendahara',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

-- --------------------------------------------------------
-- Table structure for fee_components
-- --------------------------------------------------------
DROP TABLE IF EXISTS fee_components;
CREATE TABLE fee_components (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL, -- Pokok, Air, Sampah
      amount INTEGER NOT NULL,
      effective_from TEXT NOT NULL,
      effective_until TEXT,
      description TEXT
    );

-- --------------------------------------------------------
-- Table structure for house_credits
-- --------------------------------------------------------
DROP TABLE IF EXISTS house_credits;
CREATE TABLE house_credits (
      id TEXT PRIMARY KEY,
      house_id TEXT NOT NULL,
      house_code TEXT NOT NULL,
      payment_id TEXT,
      amount INTEGER NOT NULL DEFAULT 0,
      note TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      FOREIGN KEY (house_id) REFERENCES houses(id)
    );

-- --------------------------------------------------------
-- Table structure for house_subscriptions
-- --------------------------------------------------------
DROP TABLE IF EXISTS house_subscriptions;
CREATE TABLE house_subscriptions (
      id TEXT PRIMARY KEY,
      house_id TEXT NOT NULL,
      house_code TEXT NOT NULL,
      component_id TEXT NOT NULL,
      component_name TEXT NOT NULL,
      effective_from TEXT NOT NULL,
      effective_until TEXT,
      is_active INTEGER NOT NULL DEFAULT 1,
      FOREIGN KEY (house_id) REFERENCES houses(id) ON DELETE CASCADE,
      FOREIGN KEY (component_id) REFERENCES fee_components(id)
    );

-- --------------------------------------------------------
-- Table structure for houses
-- --------------------------------------------------------
DROP TABLE IF EXISTS houses;
CREATE TABLE houses (
      id TEXT PRIMARY KEY,
      code TEXT UNIQUE NOT NULL,
      block TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'dihuni', -- dihuni, kosong, kantor
      handover_date TEXT, -- YYYY-MM-DD
      is_merged INTEGER NOT NULL DEFAULT 0,
      merged_with TEXT,
      notes TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

-- --------------------------------------------------------
-- Table structure for month_locks
-- --------------------------------------------------------
DROP TABLE IF EXISTS month_locks;
CREATE TABLE month_locks (
      id TEXT PRIMARY KEY,
      year_month TEXT UNIQUE NOT NULL, -- YYYY-MM
      status TEXT NOT NULL DEFAULT 'draft', -- draft, terkunci
      locked_by TEXT,
      locked_at TEXT,
      closing_balance_at_lock INTEGER,
      notes TEXT,
      created_at TEXT NOT NULL
    );

-- --------------------------------------------------------
-- Table structure for other_income
-- --------------------------------------------------------
DROP TABLE IF EXISTS other_income;
CREATE TABLE other_income (
      id TEXT PRIMARY KEY,
      income_number TEXT UNIQUE NOT NULL,
      date TEXT NOT NULL,
      category TEXT NOT NULL,
      description TEXT NOT NULL,
      amount INTEGER NOT NULL,
      payer TEXT,
      note TEXT,
      created_by TEXT DEFAULT 'Bendahara',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

-- --------------------------------------------------------
-- Table structure for payment_allocations
-- --------------------------------------------------------
DROP TABLE IF EXISTS payment_allocations;
CREATE TABLE payment_allocations (
      id TEXT PRIMARY KEY,
      payment_id TEXT NOT NULL,
      due_id TEXT,
      house_id TEXT NOT NULL,
      house_code TEXT NOT NULL,
      year_month TEXT NOT NULL,
      component_name TEXT NOT NULL,
      amount INTEGER NOT NULL,
      created_at TEXT NOT NULL,
      FOREIGN KEY (payment_id) REFERENCES payments(id) ON DELETE CASCADE
    );

-- --------------------------------------------------------
-- Table structure for payments
-- --------------------------------------------------------
DROP TABLE IF EXISTS payments;
CREATE TABLE payments (
      id TEXT PRIMARY KEY,
      payment_number TEXT UNIQUE NOT NULL,
      date TEXT NOT NULL,
      house_id TEXT NOT NULL,
      house_code TEXT NOT NULL,
      payer_name TEXT NOT NULL,
      amount INTEGER NOT NULL,
      method TEXT NOT NULL DEFAULT 'transfer', -- transfer, cash
      proof_photo TEXT,
      note TEXT,
      created_by TEXT DEFAULT 'Bendahara',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      FOREIGN KEY (house_id) REFERENCES houses(id)
    );

-- --------------------------------------------------------
-- Table structure for residents
-- --------------------------------------------------------
DROP TABLE IF EXISTS residents;
CREATE TABLE residents (
      id TEXT PRIMARY KEY,
      house_id TEXT NOT NULL,
      house_code TEXT NOT NULL,
      name TEXT NOT NULL,
      phone TEXT,
      email TEXT,
      start_date TEXT NOT NULL,
      end_date TEXT,
      is_active INTEGER NOT NULL DEFAULT 1,
      notes TEXT,
      created_at TEXT NOT NULL,
      FOREIGN KEY (house_id) REFERENCES houses(id) ON DELETE CASCADE
    );

-- --------------------------------------------------------
-- Table structure for sessions
-- --------------------------------------------------------
DROP TABLE IF EXISTS sessions;
CREATE TABLE sessions (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      token TEXT UNIQUE NOT NULL,
      expires_at TEXT NOT NULL,
      created_at TEXT NOT NULL,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

-- --------------------------------------------------------
-- Table structure for settings
-- --------------------------------------------------------
DROP TABLE IF EXISTS settings;
CREATE TABLE settings (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL,
      description TEXT,
      updated_at TEXT NOT NULL
    );

-- --------------------------------------------------------
-- Table structure for users
-- --------------------------------------------------------
DROP TABLE IF EXISTS users;
CREATE TABLE users (
      id TEXT PRIMARY KEY,
      username TEXT UNIQUE NOT NULL,
      name TEXT NOT NULL,
      role TEXT NOT NULL DEFAULT 'warga', -- admin, warga
      house_code TEXT,
      password_hash TEXT NOT NULL,
      phone TEXT,
      email TEXT,
      is_active INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

